#!/usr/bin/env python3
"""Single launcher for the Telegram demo; no package installation is required."""
from __future__ import annotations

import argparse
import importlib
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SOURCE_DIR = ROOT / "src"
if str(SOURCE_DIR) not in sys.path:
    sys.path.insert(0, str(SOURCE_DIR))
# Keep generated bytecode out of the project root and source tree when launched.
sys.pycache_prefix = str(ROOT / ".cache" / "python")

COMMANDS = {
    "web": ("demo_telegram", "Thu thập Telegram công khai, không cần API"),
    "api": ("demo_telegram_api", "Thu thập/đăng nhập bằng Telegram API"),
    "groups": ("find_private_groups", "Khám phá, tham gia và đọc nhóm kín"),
    "search": ("keyword_usernames", "Tìm username theo từ khoá"),
    "profile": ("username_info", "Tra hồ sơ theo username"),
    "db": ("database", "Quản lý SQLite và nhập/xuất JSON"),
    "classify": ("classify_messages", "Phân loại văn bản bằng Jev và lưu SQLite"),
    "video": ("video", "FFmpeg → Whisper/OCR/thị giác → Jev → SQLite"),
    "image": ("image", "Ảnh → OCR/thị giác → Jev → SQLite"),
    "download": ("telegram_download", "Tải đúng một video Telegram theo link bài đăng"),
    "dashboard": ("dashboard", "Mở dashboard Telegram cục bộ trên trình duyệt"),
}
LEGACY_ALIASES = {module + ".py": command for command, (module, _) in COMMANDS.items()}


def main(argv=None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    description = "Công cụ Telegram: thu thập → phân tích → SQLite.\n\n" + "\n".join(
        f"  {command:9} {description}" for command, (_, description) in COMMANDS.items()
    )
    parser = argparse.ArgumentParser(
        description=description, formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="Dùng: python3 main.py COMMAND --help để xem các tuỳ chọn chi tiết.",
    )
    parser.add_argument("command", metavar="COMMAND", help=" | ".join(COMMANDS))
    parser.add_argument("arguments", nargs=argparse.REMAINDER, help=argparse.SUPPRESS)
    if not argv:
        parser.print_help()
        return 0
    args = parser.parse_args(argv)
    command = LEGACY_ALIASES.get(args.command, args.command)
    if command not in COMMANDS:
        parser.error(f"lệnh không hợp lệ: {args.command}")
    module_name = COMMANDS[command][0]
    previous_argv = sys.argv
    try:
        # Existing CLI parsers keep their own flags, positional args and exit codes.
        sys.argv = [f"{parser.prog} {command}", *args.arguments]
        module = importlib.import_module(f"telegram_demo.cli.{module_name}")
        result = module.main()
        return 0 if result is None else result
    finally:
        sys.argv = previous_argv


if __name__ == "__main__":
    sys.exit(main())
